  "ارفع فيديو أو كذا فيديو مرة واحدة، والبرنامج يطلّع من كل واحد 🎬🔊 نسخة الصورة + المؤثرات بس. وكمان الأجزاء لوحدها: 🎬 الصورة، و🗣️ الكلام، و🎵 الموسيقى، و🔊 المؤثرات.": "Upload one video or many at once, and each one gets a 🎬🔊 picture + sound effects only version. Plus the parts on their own: 🎬 picture, 🗣️ speech, 🎵 music and 🔊 sound effects.",
  "كل نسخ «الصورة + المؤثرات»": "All \"picture + sound effects\" versions",
