  "ارفع أي فيديو والبرنامج يقسّمه لـ ٤: 🎬 الصورة من غير صوت، و🗣️ الكلام، و🎵 الموسيقى، و🔊 المؤثرات. كل جزء تسمعه لوحده وتنزّله.": "Upload any video and it gets split into 4: 🎬 the picture without sound, 🗣️ speech, 🎵 music and 🔊 sound effects. Listen to or download each part on its own.",
  "＋ فيديو للتقسيم": "＋ Video to split",
