  "من غير ذكاء اصطناعي: الحركات بالقواعد، والأيقونات من القاموس بس، والكلام بيتفرّغ على السيرفر لو متفعّل": "Without AI: moves by rules, icons from the dictionary only, and speech is transcribed on the server if enabled",
