  "📖 القاموس": "📖 Dictionary",
  "{0} معنى · {1} كلمة اتعلّمت": "{0} meanings · {1} words learned",
  "بيتملي لوحده: كل أيقونة بتتطلّع من فيديو في المعمل (أو بتترسم) بتدخل بمعناها وكلماتها عربي وإنجليزي. الكلمة اللي ميعرفهاش بيسأل عليها موديل صغير مرة واحدة ويحفظ الإجابة. ونفس المعنى ممكن يبقى ليه أيقونة مختلفة في كل ستايل: المشروع بياخد أيقونة الستايل بتاعه الأول.": "It fills itself: every icon extracted from a video in the Lab (or drawn) comes in with its meaning and words in Arabic and English. Words it doesn't know are asked once to a small model and the answer is saved. The same meaning can have a different icon in each style: a project takes its own style's icon first.",
