  "حلّل الفيديو": "Analyze the video",
  "👁️ اللي في الفيديو": "👁️ What's in the video",
  "البرنامج بيشوف الحاجات اللي في الكادر (صورة، ورقة، شاشة، وش...) وأماكنها وهي بتتحرك، عشان الكلام يتكتب جنبها أو عليها، والكلمة اللي بتشاور على حاجة (زي «me» وفيه صورتك) ما تتكتبش والحاجة نفسها تبقى مكانها. بيتعمل لوحده مع «🧠 وزّع».": "The program finds the things in the frame (photo, paper, screen, face...) and follows them as they move, so text is written next to or on them, and a word that points at something (like «me» with your photo) is not written: the thing itself takes its place. Runs by itself with «🧠 Plan».",
