  "أسرع (720)": "Faster (720)",
  "المعاينة هنا بنفس الرسم اللي هيطلع في الفيديو. الفيديو بيترسم على السيرفر فريم فريم (دقيقة تقريبًا لكل 15 ثانية).": "The preview uses the same drawing as the final video. The video is drawn on the server frame by frame (about a minute per 15 seconds).",
  "عن الفيديو (اختياري): مين بيتكلم ولمين وإيه الإحساس": "About the video (optional): who speaks, to whom, what feeling",
  "١. 🗣️ الكلام": "1. 🗣️ Words",
  "اكتب الكلام (وكل كلمة بتاخد وقت تقريبي)، أو ارفع صوت أو فيديو والكلام بيتكتب بتوقيته. لو رفعت فيديو، التايبوجرافي بيتركب فوقه.": "Type the words (each word gets an estimated time), or upload audio or video and the words are transcribed with timing. With a video, the typography goes on top of it.",
