  "🔤 اعمل فيديو بالستايل ده": "🔤 Make a video in this style",
  "تطلّع تايبوجرافي «{0}» من جديد؟ (الستايل والستيكرات القديمة بيفضلوا في المكتبة)": "Extract the typography of «{0}» again? (Old style and stickers stay in the library)",
  "يطلّع التايبوجرافي من «{0}»: الستايل، وكل لحظة الكلام اتحوّل فيها لشكل، والأيقونات كستيكرات شفافة؟": "Extract the typography from «{0}»: the style, every moment speech turned into shapes, and the icons as transparent stickers?",
  "تمسح نتيجة التايبوجرافي؟ (الستايل والستيكرات بيفضلوا في المكتبة)": "Delete the typography result? (Style and stickers stay in the library)",
  "التايبوجرافي": "Typography",
  "يطلّع كل لحظة الكلام فيها اتحوّل لكلمات أو أشكال أو أيقونات، والستايل، والأيقونات كستيكرات شفافة": "Extracts every moment where speech became words, shapes or icons, the style, and the icons as transparent stickers",
  "＋ فيديو تايبوجرافي جديد": "＋ New typography video",
  "الكلام بيتحوّل لموشن جرافيك: كلمات بتتكتب وتتبعتر وتتجمع، وحروف بتتبدل بأيقونات. من كلام بتكتبه، أو صوت، أو فيديو متصوّر (الكلام بيتركب فوقه).": "Speech becomes motion graphics: words that type, scatter and assemble, letters that swap to icons. From typed text, audio, or a filmed video (typography goes on top).",
  "الأيقونات والصور الشفافة اللي الكلام بيتحوّل لها. بتيجي من «🔤 التايبوجرافي» في معمل التفكيك، أو ترفعها، أو تترسم بالوصف.": "The transparent icons and images speech turns into. They come from «🔤 Typography» in the lab, your uploads, or drawn from a description.",
  "اعمل فيديو جديد من «＋ فيديو تايبوجرافي جديد».": "Make a new video from «＋ New typography video».",
  "🎬 عايز مونتاج أنهي مدرب؟": "🎬 Which coach do you want to edit?",
  "المشروع ده اتولّد بأكتر من مدرب. كل مدرب ليه مونتاج لوحده.": "This project was generated with more than one coach. Each coach gets their own edit.",
  "Seedance 2.5 (لحد 30 ثانية في توليدة واحدة، أغلى)": "Seedance 2.5 (up to 30 s in one generation, pricier)",
  "الفيديو أطول من {0} ثانية، فهيتولّد على {1} حتت. كل حتة بتكمّل على اللي قبلها من آخر فريم فيها، فبيفضل لقطة واحدة. (Seedance 2.5 بيعمل لحد 30 ثانية في توليدة واحدة)": "The video is longer than {0} seconds, so it will be generated in {1} pieces. Each piece continues from the last frame of the one before it, so it stays one shot. (Seedance 2.5 does up to 30 seconds in one generation)",
  "🎬 ولّد الفيديو كله مرة واحدة": "🎬 Generate the whole video in one pass",
  "ارسم الشيت أو ارفعه الأول (خطوة ٢)": "Draw or upload the sheet first (step 2)",
  "🎬 الفيديو كله مرة واحدة (لقطة متصلة)": "🎬 The whole video in one pass (one continuous shot)",
  "الشيت كله بيتبعت للموديل مرة واحدة، فبيطلّع فيديو واحد ماشي على اللوحات بالترتيب من غير ما يتقطع. محتاج الشيت بس، من غير تقطيع ولا توضيح.": "The whole sheet goes to the model at once, so it produces one video that moves through the panels in order without breaks. It only needs the sheet, no slicing or sharpening.",
  "٤. 🧩 أو جزء جزء": "4. 🧩 Or part by part",
  "(كل لوحتين = جزء، وبيتلزقوا) {0}/{1} جزء اتولد": "(every two panels = a part, stitched together) {0}/{1} parts generated",
  "يولّد الفيديو كله في توليدة واحدة من الشيت؟ حوالي {0}$": "Generate the whole video in one pass from the sheet? About ${0}",
  "Nano Banana 2 (بيلتزم بالمقاس، رخيص)": "Nano Banana 2 (keeps the size, cheap)",
  "Nano Banana Pro (أجود)": "Nano Banana Pro (best)",
  "GPT Image 2.5 (زي ChatGPT)": "GPT Image 2.5 (like ChatGPT)",
  "✅ اتغير. دوس «↻ ارسم الشيت تاني» عشان يترسم بالموديل الجديد": "✅ Changed. Press “↻ Redraw the sheet” to draw it with the new model",
  "📱 9:16 طولي (ريلز)": "📱 9:16 vertical (Reels)",
  "🖥️ 16:9 عرضي": "🖥️ 16:9 horizontal",
