  "تغيّر المقاس؟ الشيتات واللوحات والفيديوهات اللي اتعملت بالمقاس القديم هتتمسح، ولازم ترسم الشيت تاني.": "Change the size? Sheets, panels and videos made at the old size will be deleted, and the sheet must be redrawn.",
  "✂️ لقيت اللوحات في الصورة وقطعتها زي ما اترسمت، وكل لوحة اتكمّلت لـ 9:16 من غير ما يتقص منها حاجة (الأطراف المغبّشة «وضّح» بيكمّلها)": "✂️ Found the panels and cut them as drawn; each was padded to 9:16 without losing anything (“Sharpen” fills the blurred edges)",
