  "اسحب أي مربع عشان تحرّكه، واسحب الركن عشان تكبّره أو تصغّره. كل مربع لازم يغطي اللوحة بتاعته بالظبط (الرقم = رقم اللوحة).": "Drag a box to move it, drag its corner to resize it. Each box should cover its panel exactly (the number is the panel number).",
