  "اللوحات المقطوعة من الشيت صغيرة. «وضّح» بيرسم كل لوحة بجودة كاملة بنفس شكلها بالظبط. ممكن تولّد من غير توضيح بس الجودة هتبقى أقل.": "Panels cut from the sheet are small. “Sharpen” redraws each at full quality with exactly the same look. You can generate without it, at lower quality.",
