  "الشيت ده مرسوم. ترسمه تاني؟ اللوحات المقطوعة منه هتتبدل.": "This sheet is already drawn. Redraw it? The panels cut from it will be replaced.",
  "🎞️ اتفتح في مونتاج الإعلانات. الكلام العربي: «📋 انسخ الكلام بتوقيته» وضيفه هناك": "🎞️ Opened in the ads editor. For the Arabic text: “📋 Copy the text with timings” and add it there",
  "✅ اتغير. البرومبتات اتحدثت؛ ارسم الشيت تاني عشان ياخد بيه": "✅ Changed. Prompts updated; redraw the sheet to apply it",
  "الموديل بيتفرج على الفيديو كله ويطلّع مخططه: تيمبليت كامل تعمل عليه فيديوهات لعملاء تانيين": "The model watches the whole video and extracts its schema: a full template for other clients' videos",
  "التيمبليت = مخطط فيديو احترافي كامل. البرنامج بيملاه بمحتوى العميل، ويرسم كل اللقطات في شيت واحد عشان تطلع متسقة، والفيديو بيتولّد لقطة واحدة متصلة.": "A template is a full professional video schema. The app fills it with the client's content, draws all shots in one sheet so they stay consistent, and generates the video as one continuous take.",
