  "مشهد)": "scenes)",
  "الموديل بيقرر لكل مشهد: يبدّل الكلام اللي على الشاشة بس، ولا يرسم المشهد من جديد لو معناه اتغير.": "The model decides per scene: swap only the on-screen text, or redraw the scene if its meaning changed.",
  "⬆ ارفع فويس أوفر كامل": "⬆ Upload a full voice-over",
  "كل مشهد (والكونيكتور اللي بعده) بياخد طول جملته، وجملة كل مشهد بتبدأ مع أوله. لو مشهد طوله اتغير كتير، حركته بتتولد تاني وده بيبان في تمن «ولّد». التسجيل الكامل لازم يكون نفس كلام جمل الفويس أوفر اللي فوق عشان يتقطّع صح.": "Each scene (with the connector after it) takes the length of its line, and each line starts with its scene. If a scene's length changes a lot, its motion is regenerated, which shows in the Generate cost. A full recording must say the same voice-over lines as above to be split correctly.",
  "اكتب عايز تعدّل إيه في السكريبت": "Write what to change in the script",
  "✍️ السكريبت اتعدّل. راجعه، وبعدين «✨ طبّق التعديلات على الفريمات»": "✍️ Script updated. Review it, then “✨ Apply the edits to the frames”",
  "كله بالصوت الجديد": "entirely with the new voice",
  "يولّد الفويس أوفر{0}؟ (رخيص، وبيتحسب على Atlas)": "Generate the voice-over{0}? (cheap, charged on Atlas)",
  "تشيل الفويس أوفر؟ (المشاهد بتفضل بطولها الحالي)": "Remove the voice-over? (scenes keep their current lengths)",
  "فيه {0} مشهد السكريبت بتاعه اتغيّر والفريمات لسه على القديم. تكمّل من غير «✨ طبّق التعديلات على الفريمات»؟": "{0} scenes have script changes but their frames are still the old ones. Continue without “✨ Apply the edits to the frames”?",
  "فيه جمل في الفويس أوفر اتغيرت وصوتها لسه القديم. تكمّل؟": "Some voice-over lines changed and their audio is still the old one. Continue?",
