  "مثلًا: اللوجو اللي استخدمته غلط، حط اللوجو اللي في الصورة": "e.g. the logo you used is wrong, use the logo in the image",
  "🛠️ صلّح فريم (ملاحظة وصور مرجعية)": "🛠️ Fix a frame (note and reference images)",
  "📎 ارفع صورة": "📎 Upload an image",
  "علّم على الصورة الصح (اللوجو مثلًا) واكتب الملاحظة، وبعدين دوس ↻ على الفريم اللي عايز تصلّحه. الصور اللي معلّم عليها بتتبعت للموديل ويستخدمها زي ما هي بالظبط.": "Select the correct image (the logo, for example) and write the note, then press ↻ on the frame you want to fix. Selected images are sent to the model and used exactly as they are.",
