  "مثلًا: فيديو ٢٠ ثانية عن أهم ٣ مميزات في التطبيق: المدرب الشخصي، متابعة التمرين، والنتايج. الختام: حمّل التطبيق": "e.g. a 20-second video about the app's top 3 features: personal coach, workout tracking and results. Ending: download the app",
  "🎞️ فيديو بالكونيكتورز": "🎞️ Connector video",
  "البرنامج بيقرا ملف العميل والكونيكتورز اللي في المكتبة، ويكتب سيناريو كل مشهد فيه بيخلص في المكان اللي الكونيكتور يبدأ منه، والمشهد اللي بعده بيبدأ مكان ما الكونيكتور بيوصل. كتابة السيناريو ببلاش تقريبًا، والرسم والتوليد بيستنوا موافقتك.": "The app reads the client profile and the connectors in the library, and writes a script where each scene ends where a connector starts and the next scene begins where it lands. Writing the script is almost free; drawing and generating wait for your approval.",
