  "البرنامج بيكتب خطة على مقاس اللقطتين (ببلاش تقريبًا)، تراجعها وتعدّلها، وبعدين يولّد: صور مفتاحية للمراحل، وحركة بين كل صورتين بموديل فيديو بياخد صورة بداية وصورة نهاية، ويجمّع آخر A ← الكونيكتور ← أول B.": "The app writes a plan for the two shots (almost free); you review and edit it, then it generates: keyframes for the stages, motion between each pair of images with a start/end-frame video model, and assembles end of A → connector → start of B.",
