  "مستني...": "Waiting...",
  "الفيديو ده اتفكك قبل خطوة الكونيكتورز. دوس «↻ دوّر تاني» فوق.": "This video was deconstructed before the connectors step. Press “↻ Search again” above.",
  "ليه؟ (مثلًا: ده قطع عادي مش كونيكتور)": "Why? (e.g. this is a plain cut, not a connector)",
  "🧪 الوصفة (تتطبق على أي مشهدين، سطر لكل خطوة)": "🧪 Recipe (applies to any two scenes, one step per line)",
  "الموديل ملقاش كونيكتورز في الفيديو ده.": "The model found no connectors in this video.",
  "يتفرج على الفيديو تاني ويدوّر على كونيكتورز. اللي قبلته أو رفضته بيفضل": "Watches the video again for connectors. Whatever you accepted or rejected stays",
  "↻ دوّر تاني": "↻ Search again",
  "الكونيكتور = لحظة القصة فيها بتتحوّل للمشهد اللي بعده قدام عينك من غير قطع (زووم جوه حاجة، الخلفية تبقى عالم تاني، الماوس بيودّينا لمكان...). الموديل بيتفرج على الفيديو كله ويكتب لكل واحد وصفته: الشرارة، واللي بيفضل ثابت، وإيه بيتحول لإيه، والكاميرا والإيقاع. ✅ يدخل المكتبة بوصفته وفريماته.": "A connector is a moment where the story turns into the next scene before your eyes, without a cut (zooming into something, the background becoming another world, the cursor taking us somewhere...). The model watches the whole video and writes each one's recipe: the trigger, what stays fixed, what turns into what, the camera and the rhythm. ✅ adds it to the library with its recipe and keyframes.",
  "📚 الكونيكتور اتحفظ في المكتبة بوصفته": "📚 The connector was saved to the library with its recipe",
  "تمسح كل الكونيكتورز اللي اتلقطت في الفيديو ده (حتى اللي قبلتها أو رفضتها) ويدوّر من الأول؟ اللي في المكتبة بيفضل فيها.": "Clear every connector found in this video (including accepted and rejected ones) and search from scratch? What's in the library stays.",
  "قسّم الحتة هنا (عند {0})": "Split the piece here (at {0})",
  "تقسم الحتة {0} عند {1}؟": "Split piece {0} at {1}?",
  "🔀 قسّم على كل تغيير (تجريبي)": "🔀 Split on every change (experimental)",
  "يمسح كل الاقتراحات ويقترح من الصفر": "Clears every suggestion and suggests from scratch",
  "🗑️ امسح واقترح من جديد": "🗑️ Clear and suggest from scratch",
  "تمسح كل اقتراحات الكومبوننتس (حتى اللي قبلتها أو رفضتها) ويقترح من الصفر؟": "Clear all component suggestions (including accepted and rejected ones) and suggest from scratch?",
  "اللي اتحفظ في المكتبة بيفضل فيها، وأسباب الرفض بتفضل محفوظة عشان الموديل يتعلم منها.": "Whatever was saved to the library stays there, and rejection reasons are kept so the model learns from them.",
  "🗑️ امسح المكتبة كلها": "🗑️ Clear the whole library",
  "تمسح كل الأصول اللي في المكتبة ({0}) بكل نسخها؟ مفيش رجوع.": "Delete all assets in the library ({0}) with all their variants? This can't be undone.",
  "متأكد؟ المكتبة هتبقى فاضية. (الفيديوهات اللي في المعمل مش هتتمسح، والكومبوننتس اللي كنت قبلتها هترجع «لسه» وتقدر تقبلها تاني)": "Are you sure? The library will be empty. (Videos in the lab are kept, and components you accepted go back to “pending” so you can accept them again)",
  "🗑️ اتمسح {0} أصل. المكتبة فاضية": "🗑️ Deleted {0} assets. The library is empty",
  "لو البرنامج فوّت تغيير: اختار فريم من الشريط (أو وقّف الفيديو عند المكان) ودوس هنا": "If the app missed a change: pick a frame from the strip (or pause the video there) and press here",
  "✂️ قسّم هنا": "✂️ Split here",
  "اختار الفريم اللي التغيير بيبدأ عنده من الشريط، أو وقّف الفيديو بتاع الحتة عنده": "Pick the frame where the change starts from the strip, or pause the piece's video there",
  "تقسم الحتة عند {0}؟ (العناصر بتتحلل للحتتين من جديد)": "Split the piece at {0}? (Elements are analyzed again for both pieces)",
  "مفيش قطع هنا: الحركة وقفت وبدأت حركة جديدة في نفس المشهد": "No cut here: the motion paused and a new motion started in the same scene",
  "🔀 تغيير جوه المشهد": "🔀 Change within the scene",
  "لو الحتة دي واللي بعدها حركة واحدة": "If this piece and the next are one motion",
  "🔗 ادمج مع اللي بعدها": "🔗 Merge with the next",
  "🔗 اتدمجوا. لو عايز الكومبوننتس تتظبط عليهم دوس «↻ اقترح تاني»": "🔗 Merged. To fit the components to them, press “↻ Suggest again”",
  "تقسّم الفيديو من جديد على كل تغيير جوه المشهد؟ (العناصر والكومبوننتس بيتعملوا من جديد بعدها)": "Split the video again on every change within a scene? (Elements and components are redone after it)",
  "تقسّم الفيديو من جديد على القطعات بس؟ (العناصر والكومبوننتس بيتعملوا من جديد بعدها)": "Split the video again on cuts only? (Elements and components are redone after it)",
  "البرنامج بيقسم الفيديو إزاي": "How the app splits the video",
  "🔀 قسّم على كل تغيير": "🔀 Split on every change",
  "✂️ القطعات بس": "✂️ Cuts only",
  "✂️ قسّم تاني": "✂️ Split again",
  "دوس على التصميم اللي عاجبك يتختار للكاروسيل (ودوسة تانية تلغيه). البرنامج بياخد التقسيم والشكل ويلوّنه بألوان العميل ويحط كلامنا.": "Click the design you like to use it for the carousel (click again to clear). The app takes its layout and look, recolors it with the client's colors and puts our text.",
  "دوس على الستايل يتختار (ودوسة تانية تلغيه). البرنامج بياخد طريقة الرسم بس ويرسم شخصيات جديدة بألوان العميل.": "Click a style to pick it (click again to clear). The app takes only the drawing style and draws new characters in the client's colors.",
