  "＋ منشن من ملف العميل": "＋ Mention from the client profile",
  "✍️ برومبت الستوري بورد (بالمنشن من 👤 ملف العميل)": "✍️ Storyboard prompt (with mentions from 👤 the client profile)",
  "👤 اعتمد الكل وضيفهم لملف العميل": "👤 Approve all and add them to the client profile",
  "لما تعتمد، الصورة بتتحفظ في 👤 ملف العميل باسمها، وبرومبتات الستوري بورد بتعمل لها منشن (@الاسم) فصورتها الحقيقية بتتبعت مع الرسم في كل لقطة.": "When you approve, the image is saved in 👤 the client profile under its name, and storyboard prompts mention it (@name) so its real image is sent with every shot's drawing.",
  "من ملف العميل": "From the client profile",
  "👤 اعتمد وضيفه لملف العميل": "👤 Approve and add to the client profile",
  "✅ اتحفظ في ملف العميل واتربط باللقطات": "✅ Saved to the client profile and linked to the shots",
  "🧠 من ملف العميل": "🧠 From the client profile",
  "تبدأ التنفيذ من جديد من الاقتراح الحالي؟ التنفيذ ده (صوره وفيديوهاته) هيتحفظ وتقدر ترجعه بزرار «رجّع التنفيذ السابق».": "Restart production from the current proposal? This production (its images and videos) is kept and you can bring it back with “Restore previous production”.",
