  "اسم العميل؟": "Client name?",
  "تحذف العميل «{0}» بكل شاشاته ولوجوهاته؟ (إعلاناته وكاروسيلاته بتروح لأقدم عميل)": "Delete the client «{0}» with all its screens and logos? (Its ads and carousels move to the oldest client)",
