  "العميل اللي شغال عليه (دوس تغيّره)": "The client you're working on (click to change)",
  "يحط شاشات التطبيق واللوجو وصور المنتج الحقيقية من ملف العميل مكان المكونات": "Puts the real app screens, logo and product images from the client profile in place of the components",
  "بيكتب برومبت كل لقطة من جديد ويعمل منشن (@) للأبطال والمكونات اللي في ملف العميل، وبعدين يرسم بصورهم": "Rewrites every shot's prompt with mentions (@) of the characters and components in the client profile, then draws with their images",
