  "مثلًا: اللهجة السعودية البيضاء، أو العامية المصرية": "e.g. neutral Saudi dialect, or Egyptian Arabic",
  "اختار اللي يعجبك من كل حاجة وجمّعهم مع بعض (تيمبليت + ستايل + شخصيات + مدرب). كلهم اختياري، ودوسة تانية على أي حاجة تلغيها. من غير اختيار البرنامج بيرسم بستايل العميل.": "Pick what you like from each and combine them (template + style + characters + coach). All optional; click again to clear. With nothing picked, the app draws in the client's style.",
