  "هنا كل حاجة عن العميل: منتجه ومجاله وسوقه ولغته وشاشاته ولوجوهاته. البرنامج بيستنبط منها الألوان والثيم، وأي كاروسيل أو ستوري بورد أو فيديو بيستخدمهم بالظبط بدل ما يخترع.": "Everything about the client: product, field, market, language, screens and logos. The app infers colors and theme from them, and every carousel, storyboard or video uses them exactly instead of inventing.",
  "＋ عميل جديد": "＋ New client",
