  "ستايل الرسم للكاروسيل (بالإنجليزي أحسن)": "Carousel illustration style (English works best)",
  "👤 العملاء": "👤 Clients",
  "كل عميل ليه هويته (الاسم والجمهور والسوق واللغة والألوان والخط واللوجو) وأصوله، وإعلاناته وكاروسيلاته ومسلسلاته. البرنامج كله بيشتغل على العميل اللي مختاره. مكتبة الأصول ومعمل التفكيك مشتركين بين كل العملاء.": "Each client has its own identity (name, audience, market, language, colors, font and logo), assets, ads, carousels and series. The whole app works on the selected client. The asset library and the breakdown lab are shared by all clients.",
  "✏️ ملف العميل الحالي": "✏️ Current client profile",
