  "💡 الكومبوننتس المقترحة": "💡 Suggested components",
  "↻ اقترح تاني": "↻ Suggest again",
  "الموديل طلّع الحتت دي من التفكيك. اتفرج على كل واحدة: ✅ تدخل المكتبة على طول بحركتها وخلفيتها وصوتها ومفاتيح التحكم بتاعتها، ❌ ترفضها واكتب السبب عشان الاقتراحات الجاية تبقى أحسن. تقدر تظبط الاسم والبداية والنهاية قبل ما تقبل.": "The model pulled these clips from the breakdown. Watch each one: ✅ adds it to the library right away with its motion, background, sound and controls; ❌ rejects it — write why so future suggestions improve. You can adjust the name, start and end before accepting.",
  "📚 اتحفظ في المكتبة": "📚 Saved to the library",
  "تفكك الفيديو من الأول؟ (الكومبوننتس اللي قبلتها أو رفضتها بتفضل، واللي في المكتبة مش بيتمسح)": "Deconstruct the video from scratch? (Components you accepted or rejected stay, and nothing in the library is deleted)",
  "يقترح كومبوننتس جديدة؟ اللي قبلته أو رفضته بيفضل زي ما هو، ورفضك بيتبعت له عشان يتعلم منه.": "Suggest new components? Whatever you accepted or rejected stays, and your rejections are sent so it learns from them.",
  "تعيد الخطوة دي؟ (العناصر والكومبوننتس بيتعملوا من جديد بعدها)": "Redo this step? (Elements and components are redone after it)",
  "ارفع أي فيديو والبرنامج يفككه: اللقطات، وكل عنصر فيها وبيعمل إيه وإمتى، وبعدين يقترح عليك الكومبوننتس اللي تنفع تتحفظ كأصول. إنت تقبل ✅ أو ترفض ❌.": "Upload any video and the program deconstructs it: the shots and every element in them, what it does and when; then it suggests components worth saving as assets. You accept ✅ or reject ❌.",
