  "⏱️ = الوقت اتظبط على بداية الصوت اللي اتقاست بالكود (دقة 10 مللي ثانية). ▶️ بيشغّل الصوت لوحده وبيودّي الفيديو للحظته. فصل التراكات نفسها (ملف للكلام وملف للمؤثرات) محتاج خدمة خارجية، وهنضيفها لما تختارها.": "⏱️ = the time was snapped to a sound onset measured in code (10 ms precision). ▶️ plays the sound on its own and jumps the video to that moment. Separating the actual tracks (a file for speech, one for effects) needs an external service; we'll add it once you choose one.",
