  "العناصر والكلام بيتطبعوا فوق الفيديو بحركتهم. اسحب أي عنصر في المعاينة عشان تغيّر مكانه. اللقطات اللي ليها موشن متركب الستوري بورد والفيديو بتوعها بيترسموا من غير الجرافيك.": "Elements and text are printed over the video with their motion. Drag any element in the preview to move it. Shots with composited motion get their storyboard and video drawn without graphics.",
