  "مثلًا: اللوجو دايمًا في الآخر، من غير وعود صحية مبالغ فيها": "e.g. logo always at the end, no exaggerated health claims",
  "🧠 عقل الإعلان": "🧠 Ad brain",
  "🧠 طبّق عقل الإعلان": "🧠 Apply ad brain",
  "المنتج اللي الإعلان عنه": "Product this ad is for",
  "🧠 افتح عقل الإعلان": "🧠 Open ad brain",
  "هنا كل حاجة عن المنتج: نوعه ومجاله وشاشاته ولوجوهه. البرنامج بيستنبط منها الألوان والثيم، وأي ستوري بورد أو فيديو بيستخدم الشاشات واللوجو دول بالظبط بدل ما يخترع.": "Everything about the product: its type, field, screens and logos. The app infers the colors and theme from them, and every storyboard or video uses these exact screens and logos instead of inventing.",
