  "🔍 استنبط من الصور": "🔍 Infer from images",
  "بتتكتب لوحدها من اللوجو والشاشات، وتقدر تعدّلها (اللي بتعدّله بإيدك ميتغيرش لما تستنبط تاني).": "Filled in automatically from the logo and screens; you can edit it (what you edit by hand isn't changed when you infer again).",
  "الثيم": "Theme",
  "الخطوط": "Typography",
  "شكل الواجهة (بالإنجليزي للبرومبتات)": "UI look (English, for prompts)",
  "وصف اللوجو": "Logo description",
  "🎞️ بيستحضر الموشن جرافيك من الإعلان الأصلي: لقطة {0}": "🎞️ Bringing in motion graphics from the original ad: shot {0}",
  "⏳ بيستحضر الموشن...": "⏳ Bringing in motion...",
  "🎞️ استحضر الموشن من المشهد الأصلي": "🎞️ Bring in motion from the original scene",
  "يتفرج على كل مشهد في الإعلان الأصلي ويستحضر الموشن جرافيك بتاعه في اللقطة المقابلة (الموشن المكتوب + عناصر الموشن كمكونات). الموشن المكتوب دلوقتي هيتبدل، والمكونات الموجودة مش هتتلمس. تكمل؟": "It watches each scene of the original ad and brings its motion graphics into the matching shot (motion text + motion elements as components). The current motion text will be replaced; existing components won't be touched. Continue?",
  "🎞️ استحضر الموشن جرافيك": "🎞️ Bring in motion graphics",
  "⚠️ الاقتراح ده مبني على تحليل أقدم، فالموشن جرافيك الجديد مش فيه. هيتكتب من جديد بالموشن وبعدين يتاخد للتنفيذ.": "⚠️ This proposal is based on an older analysis, so the new motion graphics aren't in it. It will be rewritten with the motion and then taken to production.",
  "التالي: حدّث الاقتراح بالموشن وخده للتنفيذ ←": "Next: update the proposal with the motion and take it to production →",
  "⚠️ التحليل أو الموشن جرافيك اتغيروا بعد ما الاقتراح اتكتب، فاللقطات هنا ماشية على النسخة القديمة.": "⚠️ The analysis or motion graphics changed after the proposal was written, so these shots follow the old version.",
  "↻ حدّث الاقتراح بالموشن وخده للتنفيذ": "↻ Update the proposal with the motion and take it to production",
  "✍️ بيكتب اقتراح كوتشي بالموشن، وبعده هيبدأ التنفيذ": "✍️ Writing the KOCHI proposal with the motion, then production starts",
