  "لسه مفيش اقتراح. دوس «التالي: اكتب اقتراح كوتشي» تحت التحليل.": "No proposal yet. Press “Next: write the KOCHI proposal” under the analysis.",
  "تحلل الإعلان من الأول؟ التعديلات اللي عملتها على التحليل هتتمسح. الاقتراح الحالي هيفضل لحد ما تدوس «التالي» عشان يتكتب من التحليل الجديد.": "Re-analyze the ad from scratch? Your edits to the analysis will be lost. The current proposal stays until you press “Next” to rewrite it from the new analysis.",
