  "هيكتب اقتراح جديد من آخر نسخة من التحليل والمكونات. التعديلات اللي عملتها بإيدك في الاقتراح الحالي هتتشال. تكمل؟": "This writes a new proposal from the latest analysis and components. Your manual edits to the current proposal will be replaced. Continue?",
  "هيبدأ تنفيذ جديد من آخر نسخة من الاقتراح. التنفيذ الحالي (صوره وفيديوهاته) هيتحفظ وتقدر ترجعه بزرار «رجّع التنفيذ السابق». تكمل؟": "This starts a new production from the latest proposal. The current production (images and videos) is saved and you can bring it back with “Restore the previous production”. Continue?",
