  "↩ رجوع للإعلان": "↩ Back to the ad",
  "كل ستايل = صور بتوضح الشكل اللي عايزه (تصوير، ألوان، إضاءة). البرنامج بيشوف الصور ويكتب وصف الستايل لوحده، وتقدر تعدّله.": "Each style = images showing the look you want (filming, colors, lighting). The app looks at them and writes the style description itself; you can edit it.",
