  "دوس «⏱️ رقّم الجمل على الصوت»: البرنامج هيسمع الصوت ويقسّمه جمل بتوقيتها (حتى من غير سكريبت).": "Press “⏱️ Time lines on the audio”: the audio is transcribed and split into timed lines (even without a script).",
