  "🎬 ولّد الفيديو": "🎬 Generate video",
  "🎨 {0}/{1} ستوري بورد · ✅ {2}/{3} لقطة معتمدة · 🎬 {4}/{5} فيديو موافق عليه": "🎨 {0}/{1} storyboard · ✅ {2}/{3} shots approved · 🎬 {4}/{5} videos approved",
  "↩ الغي اعتماد الكل": "↩ Unapprove all",
  "✅ اعتمد كل اللقطات": "✅ Approve all shots",
  "هيتولد فيديو لـ {0} لقطة معتمدة بـ Seedance. نكمّل؟": "Generate videos for {0} approved shots with Seedance. Continue?",
  "لقطات لسه من غير فيديو موافق عليه: {0}": "Shots without an approved video: {0}",
  "🎬 لسه {0} لقطة من غير فيديو موافق عليه. دوس على رقم أي لقطة تفتحها. المعاينة السريعة بتحط مكانهم أسود أو النسخة المختارة.": "🎬 {0} shots still lack an approved video. Click a shot number to open it. The quick preview uses black or the selected version.",
  "اتفتحت الحلقة في محرر الفيديو": "Episode opened in the video editor",
  "وجّه الكاتب: مثلًا «خلي المشهد التاني في المطار»، «النهاية أهدى»، «جمل أقصر»... (Enter يبعت)": "Guide the writer: e.g. “move scene 2 to the airport”, “calmer ending”, “shorter lines”... (Enter sends)",
  "المسلسل": "Series",
  "كتابة الحلقة": "Write episode",
  "اللقطات والستوري بورد": "Shots & storyboard",
  "✍️ كتابة الحلقة": "✍️ Write episode",
  "البرنامج بيكتب الحلقة استكمالًا للحلقات اللي قبلها. لو في حاجة مش عاجباك اكتبله توجيهك وهو يعدّل السكريبت كله. وتقدر تعدّل بإيدك في السكريبت تحت.": "The episode is written as a continuation of earlier ones. If something isn't right, give guidance and the whole script is revised. You can also edit the script below by hand.",
  "كل مشهد يبدأ بسطر «المشهد 1 — ...»، وجمل الفويس أوفر بين « ». لما تعتمده سجّل الفويس أوفر وارفعه في الخطوة اللي بعدها.": "Each scene starts with «المشهد 1 — ...», voice-over lines inside « ». Once approved, record the voice-over and upload it in the next step.",
  "🎬 اللقطات والستوري بورد": "🎬 Shots & storyboard",
  "راجع كل لقطة: الستوري بورد والبرومبت ومدتها. عدّل أو ارسم الصورة تاني لو مش عاجباك.": "Review each shot: storyboard, prompt and duration. Edit or redraw if needed.",
  "اعتمد اللقطات اللي تمام (✅)، وبعدين «ولّد المعتمدة». الفيديو مدته على قد الجملة.": "Approve the good shots (✅), then “Generate approved”. Each video matches its line's duration.",
  "على كل فيديو: «✅ موافق» أو «🔄 واحد تاني». ولما كله يبقى موافق عليه روح للمونتاج.": "On each video: “✅ Approve” or “🔄 Another one”. When all are approved, go to the montage.",
  "🎨 ارسم الستوري بورد": "🎨 Draw storyboard",
  "🎬 ولّد المعتمدة": "🎬 Generate approved",
  "🎞️ المونتاج": "🎞️ Montage",
  "🎬 افتح في محرر الفيديو": "🎬 Open in video editor",
  "👀 معاينة سريعة": "👀 Quick preview",
  "المحرر بيفتح مشروع فيه كل لقطة بالفيديو الموافق عليه ومقصوصة على مدتها، والفويس أوفر تحتهم. تقدر تضيف موسيقى وكابشن ولوجو وتصدّر من هناك.": "The editor opens a project with each shot's approved video trimmed to its duration and the voice-over under them. Add music, captions and logo, and export from there.",
  "اتعملت الحلقة الأولى. غيّر اسمها من خانة «اسم الحلقة» لو حابب": "First episode created. Rename it in the “Episode name” box if you like.",
  "لما تخلّص هنا، دوس «2 السكريبت والصوت» فوق، أو اعمل حلقة من الجنب (＋ حلقة).": "When you're done here, click “2 Script & audio” above, or create an episode from the side (＋ Episode).",
