  "تقسيم جديد للحلقة؟ النسخ اللي اتولدت أو اترفعت هتفضل محفوظة تحت «نسخ محفوظة» وتقدر تحطها على أي لقطة.": "Split the episode again? Generated or uploaded versions stay under “Saved versions” and can go on any shot.",
