  "⚠️ {0} لقطة لسه من غير فيديو، هتطلع سودا بمدتها. تقدر تجمّع عشان تشوف الإيقاع.": "⚠️ {0} shots have no video yet and will be black for their duration. You can assemble to check the pacing.",
  "كل اللقطات جاهزة. كل لقطة بتتقص على مدتها بالظبط من الصوت، والفويس أوفر فوقهم.": "All shots ready. Each is trimmed to its exact duration from the audio, with the voice-over on top.",
  "اتحفظت في الفيديوهات الجاهزة، وتقدر تنشرها من صفحة النشر.": "Saved to finished videos; you can publish it from the Publish page.",
  "المسلسلات": "Series",
  "اسم المسلسل": "Series name",
  "مثلًا: لقطات المشهد 5 أسرع، والإضاءة دافية": "e.g. faster shots in scene 5, warm lighting",
  "⚠️ مفتاح Atlas مش متسجل. حطه من ⚙️ الإعدادات.": "⚠️ Atlas key is not set. Add it in ⚙️ Settings.",
