  "التجميع": "Assembly",
  "اسم المسلسل (للبرنامج بس، مش بيتقال في الحلقات)": "Series name (internal only, never said in episodes)",
  "دستور المسلسل (البرومبت الأساسي: الفكرة، الأسلوب، اللهجة، الممنوعات). بيتبعت للموديل مع كل حلقة": "Series bible (the main prompt: idea, style, dialect, don'ts). Sent to the model with every episode",
  "وصف الشخصية (بيتكتب في برومبت كل لقطة عشان شكلها يفضل ثابت). يفضّل بالإنجليزي": "Character description (added to every shot prompt to keep the look consistent). English is best",
  "صور الشخصية (بتتبعت مع كل لقطة بتتولد)": "Character images (sent with every generated shot)",
  "موديل اللقطات (من Atlas)": "Shots model (Atlas)",
  "موديل الفيديو": "Video model",
  "📄 من ملف .txt": "📄 From .txt file",
  "كل مشهد يبدأ بسطر «المشهد 1 — ...»، وجمل الفويس أوفر بين « ». المدد المكتوبة في السكريبت بتتجاهل: الصوت هو المرجع.": "Each scene starts with a line «المشهد 1 — ...», voice-over lines go inside « ». Durations written in the script are ignored: the audio is the reference.",
  "ملاحظات للمخرج (اختياري)": "Director notes (optional)",
  "🎙️ الفويس أوفر": "🎙️ Voice-over",
  "⬆ ارفع الصوت": "⬆ Upload audio",
  "⏱️ رقّم الجمل على الصوت": "⏱️ Time lines on the audio",
  "الجملة": "Line",
  "تبدأ": "Start",
  "تخلص": "End",
  "🎬 اللقطات": "🎬 Shots",
  "كل لقطة مدتها جاية من وقت الكلام اللي عليها. ولّد نسخ أو ارفع فيديو جاهز، ودوس على النسخة اللي عاجباك. الماوس فوق النسخة بيشغّلها.": "Each shot's duration comes from the voice-over over it. Generate versions or upload a ready video, and click the one you like. Hover a version to play it.",
  "📦 نسخ محفوظة (من تقسيمات قديمة)": "📦 Saved versions (from older splits)",
  "🎞️ تجميع الحلقة": "🎞️ Assemble episode",
  "🎞️ جمّع الحلقة": "🎞️ Assemble episode",
  "اعمل مسلسل جديد من الجنب.": "Create a new series from the side panel.",
  "امسح النسخة دي": "Delete this version",
  "نسخة {0}": "Version {0}",
  "{0} نسخ:": "{0} versions:",
  "مسح النسخة دي نهائي؟": "Delete this version permanently?",
  "ترسم نسخة جديدة لكل السلايدات؟ النسخ القديمة هتفضل محفوظة وتقدر ترجعلها.": "Draw a new version of every slide? Old versions stay saved and you can go back to them.",
  "🔄 نسخة جديدة لكل السلايدات": "🔄 New version of all slides",
  "كل نسخة بترسمها بتتحفظ تحت السلايد بتاعها. اختار النسخة اللي عاجباك من كل سلايد، ومش لازم تاخد كل السلايدات من نفس المرة.": "Every version you draw is saved under its slide. Pick the one you like for each slide; they don't have to come from the same round.",
  "{0} (قديم)": "{0} (old)",
  "مفيش {0} لسه. ضيف من 📚 المكتبة.": "No {0} yet. Add some from 📚 Library.",
  "تيمبليتس": "templates",
  "ستايلات": "styles",
  "شخصيات": "characters",
  "مفيش مدربين لسه. ضيفهم من صفحة المدربين.": "No coaches yet. Add them on the Coaches page.",
  "@{0} هيتكتب جنب صورته ويتعمله تاج في النشر": "@{0} will be written next to them and tagged when publishing",
  "⚠️ المدرب ده مالوش حساب إنستجرام متسجل (ضيفه من صفحة المدربين)": "⚠️ This coach has no Instagram account saved (add it on the Coaches page)",
  "دوس على التصميم اللي عاجبك يتختار للكاروسيل (ودوسة تانية تلغيه). البرنامج بياخد التقسيم والشكل ويلوّنه بألوان كوتشي ويحط كلامنا.": "Click a design to pick it (click again to remove). Its layout is reused, recolored in KOCHI colors with our text.",
  "البرنامج هيعمل فيديو من السلايدات بالموسيقى، ويتحفظ كمان في الفيديوهات الجاهزة. التاج في الريل بيبقى على الفيديو كله.": "A video is made from the slides with the music, and also saved to finished videos. In a Reel the tag covers the whole video.",
  "الكاروسيل بيتنشر صور بمقاس 1080×1350 على إنستجرام. تيك توك مش بيقبل كاروسيل صور من هنا، استخدم الريل.": "The carousel is posted as 1080×1350 images on Instagram. TikTok photo carousels aren't supported here, use the Reel.",
  "— من غير موسيقى —": "— No music —",
  "الميعاد ده عدّى، اختار ميعاد جاي أو دوس انشر دلوقتي": "That time has passed. Pick a future time or press Publish now",
